{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C45", "C50", "C64", "C65", "C03", "C17", "C16", "C46"],
  "contradictory_card_ids": ["C70", "C71", "C74", "C78"],
  "prediction_basis_card_ids": ["C45", "C50", "C64", "C65", "C03", "C17", "C16"],
  "claims": [
    {
      "claim": "The query is a tryptamine/triptan with a dimethylaminoethyl side chain and a pyrrolidine sulfonamide; the closest card analog zolmitriptan has high aqueous solubility (20.26 mg/mL at pH 1.2 and 9.79 mg/mL at pH 6.8) and shows concentration-linear bidirectional Caco-2 flux consistent with passive diffusion and no efflux liability, supporting favorable absorption for this structural class.",
      "card_ids": ["C45", "C50", "C64", "C65"]
    },
    {
      "claim": "L1 gold contexts with indole/basic-amine or sulfonamide features support F >= 20%: vilazodone 72% in the fed state, 5-HTP 49% in humans, and sulthiame complete oral bioavailability; no transferable direct low-F outcome is present.",
      "card_ids": ["C03", "C17", "C16"]
    },
    {
      "claim": "L6 hepatic-clearance records show that close triptan analogs (rizatriptan, 5-MeO-DMT) undergo MAO/CYP-mediated metabolism in human liver microsomes/hepatocytes, indicating potential first-pass loss; however, these are in vitro intrinsic-clearance measurements without oral F outcomes and are insufficient to establish F < 20% for the query.",
      "card_ids": ["C74", "C78", "C70", "C71"]
    },
    {
      "claim": "The sulfonamide-pyrrolidine motif is compatible with good aqueous solubility, as shown by TPN729MA (30 mg/mL in water), supporting the dissolution component of oral absorption.",
      "card_ids": ["C46"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C70", "C71", "C73", "C74", "C78"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability or IV-comparator data for the query or a close analog.",
    "L6 metabolic-stability records are for reference triptans (rizatriptan, 5-MeO-DMT, eletriptan) and imipramine, not the query; transfer is inferred from the shared dimethylaminoethyl indole motif.",
    "No human PK, dose, formulation, or prandial-state data for the query.",
    "No quantitative link between in vitro intrinsic clearance and human F for the query."
  ],
  "decision_summary": "L6 adds in vitro hepatic-clearance/metabolic-stability evidence showing MAO/CYP-mediated metabolism for close triptan analogs, a potential first-pass liability, but it does not provide direct F outcomes and is insufficient to overturn the favorable absorption/solubility evidence and supportive L1 gold contexts; prediction remains high with moderate confidence."
}

